head.script:
	scwin.onpageload = function() {
		var jsonData = [{col1:"number1", col2:1, depth:"1"}
						,{col1:"number1-1", col2:2, depth:"2"}
						,{col1:"number1-2", col2:3, depth:"2"}
						,{col1:"number2", col2:4, depth:"1"}
						,{col1:"number2-1", col2:5, depth:"2"}
						,{col1:"number2-1-1", col2:6, depth:"3"}
						,{col1:"number3", col2:7, depth:"1"}
						,{col1:"number3-1", col2:8, depth:"2"}];
		dataList1.setJSON(jsonData);
	};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('wq_uuid_3').querySelectorAll('div').length == 8;
}	

scwin.unitTest = function(){
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");		

	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
